from sales_dashboard.loader import parse_session_log
from sales_dashboard.metrics import conversion_rate, pooled_conversion_rate
from sales_dashboard.report import campaign_summary


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate(
        [{"converted": True}, {"converted": None}, {"converted": False}]
    ) == 1 / 3


def test_dedupe_sessions_keeps_the_last_duplicate_id():
    from sales_dashboard.loader import dedupe_sessions

    first = {"id": "same", "day": 1, "converted": False}
    last = {"id": "same", "day": 3, "converted": True}
    other = {"id": "other", "day": 2, "converted": False}

    assert dedupe_sessions([first, other, last]) == [other, last]


def test_parse_session_log_values_and_skipped_lines():
    assert parse_session_log(
        ["  # ignored", " ", " a , 4 , ", "b,5,0", "c,6,1"]
    ) == [
        {"id": "a", "day": 4, "converted": None},
        {"id": "b", "day": 5, "converted": False},
        {"id": "c", "day": 6, "converted": True},
    ]


def test_daily_counts_cover_inclusive_range():
    from sales_dashboard.loader import daily_conversion_counts

    events = [
        {"day": 1, "converted": True},
        {"day": 2, "converted": False},
        {"day": 3, "converted": True},
        {"day": 3, "converted": True},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 3) == [0, 2]
    assert daily_conversion_counts(events, 3, 2) == []


def test_window_and_pooled_rates_use_session_counts():
    from sales_dashboard.metrics import conversions_in_window

    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert pooled_conversion_rate(
        {"large": [{"converted": True}] * 3, "small": [{"converted": False}]}
    ) == 0.75


def test_group_rates_and_top_groups_follow_spec():
    from sales_dashboard.metrics import conversion_rate_by_group
    from sales_dashboard.report import top_converting_groups

    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "b": [{"converted": True}],
        "a": [{"converted": False}],
    }
    assert list(conversion_rate_by_group(groups)) == ["a", "b", "empty", "z"]
    assert conversion_rate_by_group(groups)["empty"] is None
    assert top_converting_groups(groups, 3) == ["b", "z", "a"]


def test_campaign_summary_rounding_and_nonempty_groups():
    groups = {
        "a": [{"id": "a", "day": 1, "converted": True}],
        "b": [{"id": "b", "day": 2, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}


def test_longest_streak_resets_after_nonpositive_day():
    from sales_dashboard.metrics import longest_conversion_streak

    assert longest_conversion_streak([2, 1, 0, 4]) == 2
    assert longest_conversion_streak([-1, 1, 0]) == 1


def test_parse_session_log_errors_include_original_line_number():
    import pytest

    with pytest.raises(ValueError, match="line 3"):
        parse_session_log(["# comment", " ", "x,nope,1"])
    with pytest.raises(ValueError, match="line 1"):
        parse_session_log(["x,1,true"])
    with pytest.raises(ValueError, match="line 1"):
        parse_session_log(["x,1"])


def test_campaign_summary_handles_no_sessions():
    assert campaign_summary({"empty": []}, 7) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_package_exports_api():
    import sales_dashboard

    assert callable(sales_dashboard.daily_conversion_counts)
    assert callable(sales_dashboard.campaign_summary)

